SELECT DISTINCT risk_level FROM (
    SELECT jsonb_extract_path_text(incident_risk_record, 'risk', 'risk_level') as risk_level 
    FROM incidentandriskmanagement
) t WHERE risk_level IS NOT NULL;

SELECT DISTINCT gdp_compliance FROM (
    SELECT jsonb_extract_path_text(qc_checklist, 'gdp_quality', 'gdp_compliance') as gdp_compliance 
    FROM qualitycompliance
) t WHERE gdp_compliance IS NOT NULL;

SELECT DISTINCT pack_condition FROM (
    SELECT jsonb_extract_path_text(qc_checklist, 'product_integrity', 'pack_condition') as pack_condition 
    FROM qualitycompliance
) t WHERE pack_condition IS NOT NULL;

SELECT DISTINCT quarantine_reason FROM (
    SELECT jsonb_extract_path_text(qc_checklist, 'release', 'quarantine_reason') as quarantine_reason 
    FROM qualitycompliance
) t WHERE quarantine_reason IS NOT NULL;

-- Check security section
SELECT jsonb_extract_path_text(qc_checklist, 'security', 'security_level') as security_level
FROM qualitycompliance LIMIT 5;

-- Check security_incident values
SELECT DISTINCT jsonb_extract_path_text(qc_checklist, 'security', 'security_incident') as security_incident
FROM qualitycompliance;

-- Check seal_status values
SELECT DISTINCT jsonb_extract_path_text(qc_checklist, 'security', 'seal_status') as seal_status
FROM qualitycompliance;
